class Solution {
    vector<string> split(const string& s) {
        vector<string> words;
        stringstream ss(s);
        string w;
        while (ss >> w) words.push_back(w);
        return words;
    }
public:
    bool areSentencesSimilar(string sentence1, string sentence2) {
        auto w1 = split(sentence1);
        auto w2 = split(sentence2);
        if (w1.size() > w2.size()) swap(w1, w2);

        int i = 0, n1 = w1.size(), n2 = w2.size();
        while (i < n1 && w1[i] == w2[i]) i++;

        int j = 0;
        while (j < n1 - i && w1[n1 - 1 - j] == w2[n2 - 1 - j]) j++;

        return i + j == n1;
    }
};

class Solution {
    public boolean areSentencesSimilar(String sentence1, String sentence2) {
        String[] w1 = sentence1.split(" ");
        String[] w2 = sentence2.split(" ");
        if (w1.length > w2.length) {
            String[] tmp = w1; w1 = w2; w2 = tmp;
        }

        int i = 0, n1 = w1.length, n2 = w2.length;
        while (i < n1 && w1[i].equals(w2[i])) i++;

        int j = 0;
        while (j < n1 - i && w1[n1 - 1 - j].equals(w2[n2 - 1 - j])) j++;

        return i + j == n1;
    }
}

